records=[];sql_steps=[]
def record(name,ok,detail=''):
    records.append(dict(name=name,passed=bool(ok),detail=detail))
    print(('PASS ' if ok else 'FAIL ')+name,flush=True)
    if not ok: raise RuntimeError(name+': '+detail)
def case(name,sql,expected=None,error=None):
    r=run(sql,check=False);out=r.stdout.decode('utf-8','replace').strip().replace('\r','');err=r.stderr.decode('utf-8','replace').strip()
    ok=(r.returncode==0 and (expected is None or out==str(expected))) if error is None else (r.returncode!=0 and error.lower() in err.lower())
    record(name,ok,('expected rejection: '+err) if error else out)
    sql_steps.append('-- '+name+'\n'+('-- 预期拒绝 '+error+'\n' if error else '')+sql)
    return out
